"""Casos simulados no navegador, seguindo o atendimento: escrever os sintomas -> conduta imediata -> cartões de decisão
-> hipóteses -> protocolo -> medicamento e cálculo -> exames -> evolução -> passagem de caso.
Uso: python3 testes/e2e.py  (CHROME=/caminho opcional)"""
import asyncio, os
URL = 'file://' + os.path.abspath(os.path.join(os.path.dirname(__file__), '..', 'dist', 'guia-ps.html'))
CHROME = os.environ.get('CHROME')
from playwright.async_api import async_playwright
R = []
def ck(n, c): R.append(bool(c)); print(('OK    ' if c else 'FALHA ') + n)
async def main():
    async with async_playwright() as p:
        b = await p.chromium.launch(**({'executable_path': CHROME} if CHROME else {}), args=['--no-sandbox'])
        pg = await b.new_page(viewport={'width': 1280, 'height': 900}); errs = []
        pg.on('pageerror', lambda e: errs.append(str(e)))
        await pg.goto(URL)
        T = lambda: pg.inner_text('#app')
        M = lambda: pg.inner_text('.modal')
        N = lambda i: pg.inner_text('#n-' + i.replace('.', '-'))
        C = lambda s: pg.click(s)
        B = lambda t: pg.click(f'button:has-text("{t}")')
        async def tem(i): return await pg.locator('#n-' + i.replace('.', '-')).count() > 0
        async def campo(sel, v): await pg.fill(sel, v); await pg.keyboard.press('Enter')
        async def escreve(t): await pg.fill('#txt', t); await pg.wait_for_timeout(50)
        async def abre(i):  # abre o cartão (não fecha se já estiver aberto)
            if not await pg.locator('#n-' + i.replace('.', '-') + '.ab').count(): await C(f'[data-a=sel][data-id="{i}"]')
        async def fechar(): await C('.modal .x')

        # ---------- chegada: nada bloqueia ----------
        t = await T(); ck('tela vazia oferece novo atendimento', 'Novo atendimento' in t)
        await C('[data-a=novo]'); t = await T()
        ck('novo atendimento abre direto na entrada por sintomas, como Paciente 01', 'Paciente 01' in t and 'Entrada por sintomas' in t and await pg.locator('#txt').count() == 1)
        ck('o cursor já está na caixa de texto', await pg.evaluate("document.activeElement.id") == 'txt')
        ck('sem sinais vitais no topo', await pg.locator('[data-c=vit]').count() == 2 and 'PAD' not in t)
        ck('manejo inicial já aparece e é o "Agora"', 'Monitorizar' in await N('agora') and 'Agora' in await N('agora'))
        ck('resumo e linha do tempo escondidos até tocar', 'Linha do tempo' not in t)
        # ---------- escrever os sintomas: conduta e hipóteses na hora ----------
        await escreve('falta de ar')
        ck('falta de ar já gera hipóteses', await tem('h.ic') and await tem('h.resp') and 'Possível' in await N('h.ic'))
        await escreve('falta de ar, inchaço nas pernas, estertores, sem dor no peito, FC 110, sat 87')
        s = await N('sint'); ck('texto vira cartões de achados', 'Falta de ar' in s and 'Inchaço nas pernas' in s and 'Estertores' in s)
        ck('negação: "sem dor no peito" fica riscado e não conta', 'sem dor no peito' in s and await pg.locator('#n-sint .ch.neg').count() == 1)
        ck('FC e saturação escritas no texto preenchem os cartões', await pg.input_value('[data-c=vit][data-k=fc]') == '110' and await pg.input_value('[data-c=vit][data-k=sat]') == '87')
        ck('saturação 87 já gera conduta: oxigênio', await tem('p.o2') and 'Dar oxigênio suplementar' in await N('p.o2'))
        h = await N('h.ic'); ck('IC compatível, com conduta enquanto isso e botão para o protocolo', 'Compatível' in h and 'VNI' in h and 'Seguir para IC e EAP' in h)
        ck('o foco continua no texto enquanto escreve', await pg.evaluate("document.activeElement.id") == 'txt')
        await abre('h.ic'); h = await N('h.ic'); ck('abrir a hipótese mostra a favor e como confirmar', 'A favor' in h and 'Estertores' in h and 'Para confirmar' in h)
        await escreve('falta de ar, estertores, FC 110, sat 87, BNP baixo')
        await C('[data-a=sel][data-id=perg]'); await C('[data-a=ex][data-id=bnp][data-st=res]'); await campo('[data-c=exval][data-id=bnp]', '60')
        await abre('h.ic'); ck('BNP 60 pesa contra IC', 'Pouco provável' in await N('h.ic') and 'BNP abaixo de 100' in await N('h.ic'))
        await abre('perg'); await campo('[data-c=exval][data-id=bnp]', '900'); ck('BNP 900 tira o contra', 'Pouco provável' not in await N('h.ic'))
        await escreve('falta de ar, inchaço nas pernas, estertores, turgência jugular, extremidades frias, hipotenso, FC 110, sat 87')
        ck('hipotenso no texto marca instabilidade', 'Sim' in await N('grav') and 'Hipotensão' in await N('grav') and await tem('p.inst'))
        await escreve('trauma, queda de moto, FC 110')
        ck('trauma reconhecido: aviso de que falta protocolo', await tem('trauma') and 'Ainda sem protocolo' in await N('trauma'))
        await escreve('falta de ar, inchaço nas pernas, estertores, turgência jugular, extremidades frias, FC 110, sat 87')
        ck('apagar do texto desfaz o achado', not await tem('trauma') and 'Hipotensão' not in await N('grav'))
        # ---------- cartões de decisão ----------
        await C('[data-a=gnao]'); ck('"Não, nenhum" resolve a instabilidade', 'Não' in await N('grav') and await pg.locator('#n-grav.feito').count() == 1)
        await abre('grav'); ck('abrir mostra cada sinal com presente e ausente', 'consciência' in await N('grav') and 'Presente' in await N('grav'))
        await C('[data-a=opc][data-id=ritmo][data-v=sem]'); ck('ECG respondido no próprio cartão', await pg.locator('#n-d-ritmo.feito').count() == 1)
        # ---------- perguntas ----------
        await abre('perg'); g = await N('perg'); ck('perguntar ao paciente e à família, com Sim, Não e ?', 'Paciente' in g and 'Família ou acompanhante' in g and 'Quais remédios toma?' in g)
        await C('[data-a=pg][data-id=orto][data-v=s]'); ck('pergunta respondida conta no cartão', '1/4' in await N('perg'))
        # ---------- hipótese -> protocolo levando os dados ----------
        await C('[data-a=ir][data-h=ic]'); t = await T()
        ck('abre o protocolo de IC no mesmo paciente, com a trilha', 'Sinais e sintomas' in t and 'IC e EAP' in t and await tem('d.cong'))
        ck('os achados foram junto: congestão e perfusão já marcadas', 'Sim' in await N('d.cong') and 'Estertores' in await N('d.cong') and await pg.locator('#n-d-perf.feito').count() == 1)
        await abre('perg'); ck('pergunta respondida antes continua respondida', await pg.get_attribute('[data-a=pg][data-id=orto][data-v=s]', 'class') == 'b on')
        ck('PAS só é pedida agora, porque decide a conduta', await tem('v.pas') and 'define vasodilatador' in await N('v.pas'))
        ck('sem PAS a conduta diz o que falta', await tem('falta') and 'PAS' in await N('falta'))
        await campo('[data-c=vit][data-k=pas]', 'abc'); ck('PAS inválida não é aceita', 'Digite só o número' in await N('v.pas'))
        await campo('[data-c=vit][data-k=pas]', '85'); c = await N('p.Cb')
        ck('perfil C com PAS 85: dobutamina e noradrenalina, numeradas', 'Dobutamina' in c and 'Noradrenalina' in c and '1º' in c and '2º' in c)
        ck('classificação sugerida, não confirmada', 'C · frio e úmido' in await N('cls') and 'Sugerido' in await N('cls'))
        await C('[data-a=okcls]'); ck('médico confirma a classificação', 'Confirmado' in await N('cls'))
        ck('alerta de choque cardiogênico como hipótese', await tem('a.cc') and 'Fluxo ainda não está no aplicativo' in await N('a.cc'))
        # corrigir um dado revisa a conduta
        await C('[data-a=ach][data-id=perf][data-v=a]'); t = await T()
        ck('corrigir perfusão muda a conduta e avisa', 'A conduta mudou' in t and await tem('p.B') and not await tem('p.Cb'))
        ck('classificação volta a ser sugestão', 'Sugerido' in await N('cls')); await C('[data-a=okmud]')
        await campo('[data-c=vit][data-k=pas]', '180'); c = await N('p.B'); ck('perfil B, PAS 180: furosemida e nitroglicerina', 'Furosemida' in c and 'Nitroglicerina' in c)
        ck('cartão do medicamento: quanto, repetir e máximo', '20 a 40 mg EV' in c and 'reavaliar em 6 h' in c and '600 mg por dia' in c)
        # ---------- medicamento ----------
        await C('[data-a=med][data-id=furosemida]'); m = await M()
        ck('pop-up abre com quanto, repetir e máximo no topo', m.index('Quanto') < m.index('Calcular') and 'Repetir' in m)
        ck('sem dados não calcula e diz o que falta', 'Para calcular, informe' in m and 'Volume a aspirar' not in m)
        await C('[data-a=madm]'); ck('não registra sem completar o cálculo', 'Complete o cálculo' in await M())
        await C('[data-a=cuso][data-v=s]'); await campo('.cc[data-k=oral]', '80'); await C('[data-a=cdose][data-v="160"]')
        ck('usuário de 80 mg/dia × 2 = 160 mg = 16 mL, com fórmula', '16 mL' in await M() and '160 mg ÷ 10 mg/mL' in await M())
        await C('[data-a=mpresc]'); ck('prescrito fica separado', 'Prescrito: 160 mg (16 mL)' in await M()); await C('[data-a=madm]')
        ck('administrado aparece no cartão com a hora', '1×' in await N('p.B'))
        ck('reavaliação da diurese com horário', await tem('r.diur') and 'às' in await N('r.diur'))
        await C('[data-a=med][data-id=nitroglicerina]'); m = await M()
        ck('infusão não presume preparo', 'número de ampolas' in m); ck('bolus por PAS 180 = 4 mL', '4 mL em bolus' in m)
        await C('[data-a=cprep]'); await C('[data-a=cd][data-v="10"]'); m = await M()
        ck('nitroglicerina: 250 = 10 + 240 mL, 200 mcg/mL, 10 mcg/min = 3 mL/h', '250 mL = 10 mL do medicamento + 240 mL de diluente' in m and '200 mcg/mL' in m and '3 mL/h' in m)
        await pg.fill('.cc[data-k=d]', '250'); ck('dose acima do máximo bloqueia', 'acima do máximo documentado' in await M()); await fechar()
        await C('[data-a=pg][data-id=pde5][data-v=s]'); c = await N('p.B'); ck('usou sildenafila: nitroglicerina sai e o site avisa', 'contraindicada' in c and 'Nitroglicerina' not in c.replace('Nitroglicerina contraindicada', ''))
        # ---------- exames ----------
        await abre('perg'); await C('[data-a=ex][data-id=tropo][data-st=agu]'); ck('exame aguardando entra no resumo', True)
        await C('[data-a=ex][data-id=rx][data-st=res]'); await C('[data-a=exr][data-id=rx][data-v=nsi]'); ck('não sei interpretar não vira normal', 'Nada é presumido normal' in await N('perg'))
        await C('[data-a=ex][data-id=ecg][data-st=res]'); await C('[data-a=exr][data-id=ecg][data-v=taqui]')
        ck('ECG com taquiarritmia sugere outro fluxo', await tem('a.taqui') and 'Seguir para Taquiarritmias' in await N('a.taqui'))
        # ---------- evolução ----------
        await C('[data-a=resp][data-id=diur][data-v=nao]'); ck('diurese insuficiente: dobrar a dose', 'Dobrar a dose' in await N('r.diur'))
        # ---------- resumo e passagem ----------
        await C('[data-a=resumo]'); m = await M(); ck('resumo abre só ao tocar, com pendências e linha do tempo', 'Fazer agora' in m and 'Troponina (aguardando' in m and 'Linha do tempo' in m); await fechar()
        await C('[data-a=edit]'); await campo('[data-c=nome]', 'J.S.'); await campo('[data-c=idade]', '68'); await campo('[data-c=leito]', '4'); await C('[data-a=edit]')
        ck('cabeçalho: nome, idade e leito', 'J.S.' in await pg.inner_text('.top') and '68 anos' in await pg.inner_text('.top') and 'Leito 4' in await pg.inner_text('.top'))
        await B('Passagem de caso'); r = await pg.input_value('#pass')
        ck('passagem: identificação, relato, vitais iniciais e recentes', 'J.S., 68 anos, leito 4' in r and 'falta de ar, inchaço' in r and 'PAS 85' in r and 'PAS 180' in r)
        ck('passagem: os dois fluxos, hipóteses como sugestão', 'AVALIAÇÃO POR SINAIS E SINTOMAS' in r and 'sem confirmação' in r and 'INSUFICIÊNCIA CARDÍACA' in r)
        ck('passagem: medicamento administrado com hora; consultado não entra', 'Furosemida 160 mg (16 mL) às' in r and 'Nitroglicerina' not in r.split('MEDICAMENTOS ADMINISTRADOS')[-1].split('RESPOSTA')[0])
        await C('[data-a=pdet][data-v="1"]'); ck('versão detalhada tem a linha do tempo', 'LINHA DO TEMPO' in await pg.input_value('#pass')); await fechar()

        # ---------- outro paciente: bradiarritmia direto para a doença ----------
        await C('[data-a=novo]'); ck('segundo paciente vazio, sem dados do primeiro', await pg.input_value('#txt') == '' and 'J.S.' not in await pg.inner_text('.top'))
        await C('[data-a=modo][data-v=doenca]'); await C('[data-a=tema][data-id=bradi]'); t = await T()
        ck('direto para a doença abre a bradiarritmia', await tem('grav') and 'Via aérea' in await N('agora'))
        ck('bradiarritmia não pede sinais vitais', await pg.locator('[data-c=vit]').count() == 0)
        await abre('grav'); await C('[data-a=ach][data-id=choque][data-v=p]'); c = await N('p.inst')
        ck('instável: atropina, marca-passo, adrenalina, numerados', 'Atropina' in c and 'Marca-passo' in c and 'Adrenalina em bomba' in c and '1º' in c and '3º' in c)
        await C('[data-a=med][data-id=atropina]'); ck('atropina não presume a ampola', 'apresentação da ampola' in await M())
        await C('[data-a=cap][data-v="0"]'); ck('1 mg com ampola 0,25 = 4 mL', '4 de 0,25 mg/1 mL' in await M())
        await C('[data-a=cap][data-v="1"]'); ck('1 mg com ampola 0,5 = 2 mL', '2 de 0,5 mg/1 mL' in await M()); await C('[data-a=madm]')
        c = await N('p.inst'); ck('cartão: 1/3 doses e hora da próxima', '1/3' in c and 'próxima' in c)
        for i in range(2): await C('[data-a=med][data-id=atropina]'); await C('[data-a=cap][data-v="1"]'); await C('[data-a=madm]')
        ck('3/3: máximo atingido', '3/3' in await N('p.inst') and 'máximo' in await N('p.inst'))
        await C('[data-a=med][data-id=atropina]'); await C('[data-a=cap][data-v="1"]'); await C('[data-a=madm]'); ck('4ª dose bloqueada', 'máximo de doses' in await M()); await fechar()
        await C('[data-a=med][data-id=dopamina]'); await C('[data-a=cprep]'); await C('[data-a=cd][data-v="5"]'); ck('dopamina sem peso não calcula', 'peso' in (await M()).split('Para calcular')[-1])
        await pg.fill('.cc[data-k=peso]', '70'); ck('dopamina 70 kg, 5 mcg/kg/min = 21 mL/h', '21 mL/h' in await M()); await fechar()
        await C('[data-a=resp][data-id=resp][data-v=sempulso]'); ck('perdeu o pulso sugere PCR', await tem('a.pcr'))
        await C('[data-a=ir][data-al=pcr]'); ck('PCR abre no mesmo paciente', 'Iniciar RCP' in await N('agora'))
        await C('[data-a=opc][data-id=ritmo][data-v=choc]'); c = await N('p.choc'); ck('ritmo chocável: choque e dica do 1º choque', 'Dar o 1º choque' in c)
        await C('[data-a=rep][data-id=choque]'); await C('[data-a=rep][data-id=choque]'); ck('2 choques: adrenalina', 'adrenalina 1 mg' in await N('p.choc') and '2×' in await N('p.choc'))
        await C('[data-a=med][data-id=adrenalinaPcr]'); await C('[data-a=madm]'); ck('lembrete da próxima adrenalina no resumo', True)
        await C('[data-a=resumo]'); ck('resumo traz a próxima adrenalina', 'Adrenalina de novo a partir das' in await M()); await fechar()
        await C('[data-a=resp][data-id=ritmo2][data-v=rosc]'); ck('voltou o pulso: pós-PCR', await tem('p.rosc'))

        # ---------- taquiarritmia ----------
        await C('[data-a=novo]'); await escreve('palpitação, FC 180, asma')
        ck('palpitação e FC 180 sugerem taquiarritmia, compatível', await tem('h.taqui') and 'Compatível' in await N('h.taqui'))
        await abre('h.taqui'); ck('a favor mostra FC 180', 'FC de 180' in await N('h.taqui'))
        await C('[data-a=ir][data-h=taqui]'); await C('[data-a=gnao]'); await C('[data-a=opc][data-id=ritmo][data-v=estreito]'); c = await N('p.tpsv')
        ck('TPSV estável: manobra vagal, adenosina, metoprolol', 'Manobra vagal' in c and 'Adenosina' in c and 'Metoprolol' in c)
        ck('"asma" escrito no texto já tira a adenosina', 'Adenosina contraindicada' in c)
        await C('[data-a=opc][data-id=ritmo][data-v=fa]'); ck('FA pede pré-excitação e IC', await tem('d.wpw') and await tem('d.ic'))
        await C('[data-a=ach][data-id=wpw][data-v=a]'); await C('[data-a=ach][data-id=ic][data-v=p]'); c = await N('p.fa'); ck('FA com IC: amiodarona', 'Amiodarona' in c and 'Metoprolol' not in c)
        await C('[data-a=ach][data-id=wpw][data-v=p]'); ck('FA com WPW: cardioversão 200 J', '200 J' in await N('p.cve'))

        # ---------- história escrita no texto ----------
        await C('[data-a=novo]'); await escreve('desmaio, FC 38, usa atenolol'); await abre('h.bradi')
        ck('"usa atenolol" conta a favor da bradiarritmia', 'Usa remédio que baixa a frequência' in await N('h.bradi') and 'FC de 38' in await N('h.bradi'))
        await C('[data-a=ir][data-h=bradi]'); await abre('perg'); ck('a resposta segue para o protocolo', await pg.get_attribute('[data-a=pg][data-id=remed][data-v=s]', 'class') == 'b on')
        # ---------- persistência e celular ----------
        await pg.reload(); ck('recarregar mantém os pacientes', await pg.locator('.pb').count() == 5)
        await C('.pb >> nth=0'); ck('primeiro paciente intacto', 'J.S.' in await pg.inner_text('.top') and await pg.input_value('[data-c=vit][data-k=pas]') == '180')
        await pg.set_viewport_size({'width': 390, 'height': 800}); w = await pg.evaluate('document.documentElement.scrollWidth')
        ck('celular: sem rolagem horizontal', w <= 392)
        ck('celular: setas entre os cartões continuam visíveis', await pg.locator('.seta:not(.fim)').count() > 3)
        await C('[data-a=med][data-id=furosemida]'); ck('celular: pop-up ocupa a tela', await pg.evaluate('document.querySelector(".modal").offsetWidth') >= 388); await fechar()
        ck('sem erros de JavaScript', not errs); print(errs[:3])
        await b.close()
    print(f"\n{sum(R)} passaram, {len(R)-sum(R)} falharam")
asyncio.run(main())
